// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und
// werden in der Data Table pw_config gepflegt (n8n-Oberfläche,
// "Data Tables"). HIER stehen nur die FACHLICHEN Werte dieses Workflows.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};

// ══ KANALWAHL: steht in pw_config, nicht hier ═══════════════════
// Welcher Weg zum Steuerberater benutzt wird, entscheidet der
// Schlüssel "steuer_kanal" in der Data Table pw_config, umstellbar in
// der n8n-Oberfläche unter "Data Tables", ohne Deploy.
//
// WARUM NICHT FEST VERDRAHTET:
// Die Workflow-Dateien unter n8n/ teilen sich ALLE Instanzen. Steht der
// Kanal in der Datei, bekommt jede Instanz beim Einspielen denselben -
// eine Installation fährt aber DUO, eine andere sevDesk. Instanz-
// spezifisches gehört in pw_config, und genau dafür gibt es sie.
//
// Ein Kanal ist ein Adresspaar plus ein Versand-Sub. sevDesk hat einen
// EIGENEN Absender: die Autobox verwirft Mail von nicht hinterlegten
// Adressen stillschweigend.
const kanaele = {
  duo:     { name: 'DUO',     empf: 'mail_duo',     abs: 'mail_absender',         sub: 'pwSubDuoVersand' },
  // DUO mit paper-werk: bei XRechnung geht das XML als zweiter
  // Anhang mit. Nur mit paper-werk, siehe sub-duo-versand-paperwerk.
  duo_paperwerk: { name: 'DUO', empf: 'mail_duo', abs: 'mail_absender', sub: 'pwSubDuoVersPW1' },
  stb:     { name: 'StB',     empf: 'mail_stb',     abs: 'mail_absender',         sub: 'pwSubStbVersand' },
  sevdesk: { name: 'sevDesk', empf: 'mail_sevdesk', abs: 'mail_sevdesk_absender', sub: 'pwSubSevdeskVer' }
};
const gewaehlt = String(pw('steuer_kanal')).trim().toLowerCase();
const kanal = kanaele[gewaehlt];
if (!kanal) {
  throw new Error('pw_config: "steuer_kanal" steht auf "' + gewaehlt + '"; erlaubt sind: ' + Object.keys(kanaele).join(', ') + '.');
}
// ════════════════════════════════════════════════════════════════

// zeitraum: Label für Betreff und Dateinamen. Beim Lauf am 1. des
//   Monats ist das der gerade abgeschlossene Vormonat. Berechnet,
//   nicht konfiguriert, sonst müsste es jemand jeden Monat ändern.
const now = new Date();
const prev = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const zeitraum = prev.getFullYear() + '-' + String(prev.getMonth() + 1).padStart(2, '0');

return [{
  json: {
    // ── aus pw_config ──
    paperless_url: pw('paperless_url'),
    report_email: pw('mail_betrieb'),
    kanal: kanal.name,
    empfaenger: pw(kanal.empf),
    absender: pw(kanal.abs),
    // Welchen Sub der Knoten "Versand ausführen" ruft, als Ausdruck,
    // damit die Kanalwahl an EINER Stelle bleibt.
    versand_sub: kanal.sub,

    // ── fachlich, hier zu pflegen ──
    // tag_buchungsrelevant: das AUSWAHLKRITERIUM. Eine fachliche
    //   Eigenschaft, kein Kommando; sie bleibt dauerhaft am Dokument.
    // tag_gesendet: ERGEBNIS, vom Versand-Sub gesetzt. Schließt den
    //   Beleg für alle künftigen Läufe aus.
    // tag_pending:  global. Wer gerade in Bearbeitung ist, bleibt
    //   außen vor, sonst versenden zwei Läufe denselben Beleg.
    tag_buchungsrelevant: 'buchungsrelevant',
    tag_gesendet: 'Steuer-gesendet',
    tag_pending: 'wird bearbeitet',

    dateiname_quelle: 'titel',
    zeitraum
  }
}];

// Tag-Namen aus der Konfiguration in Paperless-IDs auflösen.
// Fehlt einer, ist das ein Einrichtungsfehler; hier wird geworfen,
// damit es auffällt und nicht still nichts passiert.
const cfg = $('Konfiguration').first().json;
const tags = $json.results || [];
const finde = (name) => tags.find(t => String(t.name).toLowerCase() === String(name).toLowerCase());

const rel = finde(cfg.tag_buchungsrelevant);
const gesendet = finde(cfg.tag_gesendet);
const pending = finde(cfg.tag_pending);

if (!rel) throw new Error('Tag "' + cfg.tag_buchungsrelevant + '" existiert nicht in Paperless; bitte anlegen.');
if (!gesendet) throw new Error('Tag "' + cfg.tag_gesendet + '" existiert nicht in Paperless; bitte anlegen.');
if (!pending) throw new Error('Tag "' + cfg.tag_pending + '" existiert nicht in Paperless; bitte anlegen (das globale "wird bearbeitet").');
if (String(cfg.empfaenger).indexOf('@') === -1) throw new Error('Die Empfängeradresse für den Kanal ' + cfg.kanal + ' ist nicht gesetzt; in der n8n-Oberfläche unter "Data Tables" eintragen.');

return [{ json: Object.assign({}, cfg, {
  tag_buchungsrelevant_id: rel.id,
  tag_gesendet_id: gesendet.id,
  tag_pending_id: pending.id
}) }];

// Bericht für den Betreiber aufbauen.
// Läuft in BEIDEN Zweigen; im "keine Belege"-Fall hat "Versand
// ausführen" nie ausgeführt und der Zugriff wirft; das wird abgefangen.
const cfg = $('Tag-IDs ermitteln').first().json;
const gesamt = $('Belege auswählen').first().json.count ?? 0;

let versand = null;
try { versand = $('Versand ausführen').first().json; } catch (e) { versand = null; }
const belege = versand?.belege ?? [];

const heute = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin' });
const datum = (d) => d ? new Date(d).toLocaleDateString('de-DE') : '-';
const zeilen = belege.map(b => '<li>' + b.titel + ' (erstellt ' + datum(b.created) + ')</li>').join('');

let rumpf;
if (!belege.length) {
  rumpf = '<p>Keine neuen buchungsrelevanten Belege gefunden, nichts übermittelt.</p>';
} else {
  rumpf = '<p><strong>' + belege.length + ' Beleg(e)</strong> über den Kanal <strong>' + (versand?.kanal ?? cfg.kanal) + '</strong> an ' + cfg.empfaenger + ' übermittelt:</p><ul>' + zeilen + '</ul>';
}

// Die Auswahl deckelt bei 250. Liegt mehr an, muss der Mensch das
// wissen, sonst wartet der Rest still bis zum nächsten Monat.
const rest = gesamt - belege.length;
if (belege.length && rest > 0) {
  rumpf += '<p style="color:#c1121f;"><strong>Achtung:</strong> Es liegen noch ' + rest + ' weitere Beleg(e) an, die dieser Lauf nicht mitgenommen hat (Grenze 250 pro Lauf). Den Workflow einfach noch einmal manuell starten; er verschickt nur, was noch offen ist.</p>';
}

return [{ json: {
  subject: 'Steuerbelege ' + cfg.zeitraum + ': ' + belege.length + ' Beleg(e) übermittelt',
  html: '<div style="font-family:Arial,sans-serif;max-width:700px;">' + rumpf + '<p style="color:#95a5a6;font-size:12px;margin-top:24px;border-top:1px solid #eee;padding-top:12px;">Automatisch generiert am ' + heute + ' · <a href="https://github.com/paper-werk">Paper-Werk</a></p></div>',
  report_email: cfg.report_email,
  absender: cfg.absender,
  anzahl: belege.length,
  offen: Math.max(0, rest)
}}];
